INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (404, 1, '기본 테이블', 'iptables 에서 **-t 를 주지 않으면** 어느 테이블에 명령이 적용될까요?', '이름이 필터링을 뜻해요.', NULL, NULL, '[]', 'choice', '["nat 테이블", "mangle 테이블", "filter 테이블", "raw 테이블"]', 2, 'iptables 매뉴얼은 filter 가 -t 옵션을 주지 않으면 쓰이는 기본 테이블이며 내장 체인이 INPUT·FORWARD·OUTPUT 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 2, 'filter 의 체인', 'filter 테이블의 **내장 체인** 은 무엇일까요?', '세 가지예요.', NULL, NULL, '[]', 'choice', '["PREROUTING, INPUT, POSTROUTING", "INPUT, FORWARD, OUTPUT", "PREROUTING, OUTPUT, POSTROUTING", "INPUT, OUTPUT, MASQUERADE"]', 1, '문서는 filter 의 내장 체인이 INPUT, FORWARD, OUTPUT 이라고 설명합니다. PREROUTING·POSTROUTING 은 nat 의 체인입니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 3, 'nat 의 체인', 'nat 테이블의 **내장 체인** 은 무엇일까요?', '주소 변환은 라우팅 전후에 일어나요.', NULL, NULL, '[]', 'choice', '["PREROUTING, OUTPUT, POSTROUTING", "INPUT, FORWARD, OUTPUT", "INPUT, OUTPUT, POSTROUTING", "PREROUTING, FORWARD, INPUT"]', 0, '문서는 nat 테이블의 내장 체인이 PREROUTING, OUTPUT, POSTROUTING 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 4, '-A 와 -I', '**-I** (insert) 에서 규칙 번호를 주지 않으면 규칙은 어디에 들어갈까요?', '-A 와 반대쪽이에요.', NULL, NULL, '[]', 'choice', '["체인의 맨 끝", "체인의 가운데", "새 사용자 정의 체인", "체인의 맨 앞(머리)"]', 3, '문서는 -A 가 체인의 끝에 규칙을 추가하고, -I 는 지정한 번호에 삽입하며 번호가 없으면 체인의 머리에 넣는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 5, '-F 의 범위', '**iptables -F** 에 체인 이름을 주지 않으면 어떻게 될까요?', '비우는 범위가 넓어져요.', NULL, NULL, '[]', 'choice', '["INPUT 체인만 비워진다", "정책(policy)이 모두 DROP 으로 바뀐다", "테이블의 모든 체인의 규칙이 비워진다", "오류가 나고 아무 일도 일어나지 않는다"]', 2, '문서는 -F 가 선택한 체인을 비우며 체인을 주지 않으면 테이블의 모든 체인을 비운다고 설명합니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 6, 'RETURN 타깃', '**RETURN** 타깃은 무엇을 할까요?', '호출한 쪽으로 돌아가요.', NULL, NULL, '[]', 'choice', '["패킷을 허용하고 즉시 처리를 끝낸다", "호출한 체인의 다음 규칙으로 돌아간다", "패킷을 조용히 버리고 처리를 끝낸다", "패킷을 사용자 공간으로 넘겨 준다"]', 1, '문서는 RETURN 을 이 체인의 탐색을 멈추고 이전(호출) 체인의 다음 규칙에서 재개하는 것으로 설명합니다. 허용은 ACCEPT, 버림은 DROP, 사용자 공간 전달은 QUEUE 입니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 7, '규칙 평가 순서', '체인의 규칙은 **어떤 순서** 로 평가될까요?', '위에서부터예요.', NULL, NULL, '[]', 'choice', '["위에서부터 차례로 보고 일치하면 그 타깃이 처리를 정한다", "모든 규칙을 평가한 뒤 가장 구체적인 것을 고른다", "번호가 큰 규칙부터 평가한다", "규칙을 병렬로 평가해 가장 먼저 끝난 것을 쓴다"]', 0, '문서는 규칙을 차례로 확인하며, 일치하지 않으면 다음 규칙을 보고 일치하면 타깃이 이후를 정한다고 설명합니다. 내장 체인이 결정 없이 끝나면 체인 정책이 패킷의 운명을 정합니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 8, '-n 옵션', '`iptables -L` 에 **-n** 을 붙이면 무엇이 달라질까요?', '이름 풀이를 안 해요.', NULL, NULL, '[]', 'choice', '["규칙을 번호와 함께 출력한다", "패킷·바이트 카운터도 출력한다", "새로 만든 규칙만 출력한다", "IP·포트를 숫자로 출력한다"]', 3, '문서는 -n(--numeric)이 IP 주소와 포트를 숫자 형식으로 출력하게 한다고 설명합니다. 줄 번호는 --line-numbers, 카운터는 -v 입니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 9, '--dport 의 전제', '**--dport** 를 쓰려면 무엇이 먼저 필요할까요?', '프로토콜 확장이에요.', NULL, NULL, '[]', 'choice', '["-t nat 로 테이블을 바꿔 두어야 한다", "-s 로 출발지를 먼저 지정해야 한다", "-p tcp/udp 확장이 먼저 필요하다", "-j 타깃을 먼저 적어 두어야 한다"]', 2, '문서는 --dport 가 tcp·udp 확장의 옵션이며 이 확장은 -p tcp 또는 -p udp 로 불러온다고 설명합니다.', NULL, NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 10, '규칙을 끝에 추가', '체인의 **끝에 규칙을 추가** 하는 옵션입니다. 빈칸을 채우세요.', 'append 의 머리글자예요.', NULL, NULL, '[]', 'fill', '["A", "I", "D", "F"]', NULL, '-A(--append)는 선택한 체인의 끝에 규칙을 추가합니다. -I 는 머리나 지정 번호에 삽입, -D 는 삭제, -F 는 비우기입니다.', '[0]', 'iptables -{0} INPUT -p tcp --dport 22 -j ACCEPT', NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 11, '규칙 목록 보기', '체인의 **규칙을 나열** 하는 옵션입니다. 빈칸을 채우세요.', 'list 의 머리글자예요.', NULL, NULL, '[]', 'fill', '["L", "F", "P", "N"]', NULL, '-L(--list)은 선택한 체인의 모든 규칙을 나열하며 체인을 주지 않으면 모든 체인을 나열합니다.', '[0]', 'iptables -t nat -{0} -n', NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]'),
  (404, 12, '규칙을 앞에 끼워 넣기', '기존 규칙 앞에 새 허용 규칙을 끼워 넣어 확인하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '확인 → 삽입 → 재확인이에요.', NULL, NULL, '[]', 'order', '["iptables -L -n --line-numbers 로 현재 규칙과 번호를 확인한다", "iptables -I 로 원하는 위치에 새 규칙을 끼워 넣는다", "다시 목록을 열어 규칙 순서가 의도대로인지 확인한다", "필요하면 -D 로 잘못 넣은 규칙을 번호로 지운다"]', NULL, '문서가 설명한 -L·--line-numbers·-I·-D 를 이은 큰 줄기입니다. 규칙은 위에서부터 평가되므로 삽입 위치가 중요합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "iptables 매뉴얼", "url": "https://linux.die.net/man/8/iptables"}]');
